int zaehler = 0;
void Zaehle()
{
    for (int i = 0; i < 10_000_000; i++)
        zaehler++;
}
var a = new Thread(Zaehle);
var b = new Thread(Zaehle);
a.Start(); b.Start();
a.Join(); b.Join();
Console.WriteLine(zaehler);
// z. B. 15903337 (statt 20000000)

int frei = 1, buchungen = 0;
void Buchen()
{
    if (frei > 0)
    {
        Thread.Sleep(10); // Zahlung
        frei--;
        buchungen++;
    }
}
var k1 = new Thread(Buchen);
var k2 = new Thread(Buchen);
k1.Start(); k2.Start();
k1.Join(); k2.Join();
Console.WriteLine(
    $"frei {frei}, Buchungen {buchungen}");
// frei -1, Buchungen 2

object sperre = new();
void Buchen()
{
    lock (sperre)
    {
        if (frei > 0)
        {
            Thread.Sleep(10);
            frei--;
            buchungen++;
        }
    }
}
// frei 0, Buchungen 1

